-- GENERATED by scripts/db_export_schema.py from the live database. Do not hand-edit.
CREATE OR REPLACE FUNCTION digest.chat_recommendations_v3(p_phone text)
 RETURNS TABLE(chat_name text, verification_required boolean, requirement text, qualifies boolean, join_link text, why text, strength_note text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'digest', 'pg_temp'
AS $function$
declare v_atid text;
begin
  select m.at_member_id into v_atid from digest.members m
   where m.phone = p_phone and digest.is_active_member_status(m.membership_status);

  return query
  with v2 as (
    select t.* from digest.chat_recommendations_v2(p_phone)
      with ordinality as t(chat_name, verification_required, requirement, qualifies,
                           join_link, why, ord)
  ), me as (
    select tp.topic, tp.is_working_on from digest.member_topic_profile(v_atid) tp
  ), dos as (
    -- chats have no dossier of their own; the CHAPTER dossier of the same name is the
    -- closest content profile we hold, else nothing (never invented)
    select v.chat_name cn, ed.strength_note snote, f.topics
    from v2 v
    left join digest.entity_dossier ed on ed.kind = 'chapter' and ed.name = v.chat_name
    left join lateral (
      select array_agg(m.topic order by m.is_working_on desc) topics
      from me m
      where ed.topic_profile ? m.topic and (ed.topic_profile->>m.topic)::numeric >= 0.2
    ) f on true
  )
  select v.chat_name, v.verification_required, v.requirement, v.qualifies, v.join_link,
         coalesce(v.why, case when d.topics is not null and array_length(d.topics,1) > 0
              then 'fits your focus: ' || array_to_string(d.topics[1:2], ', ') end),
         d.snote
  from v2 v left join dos d on d.cn = v.chat_name
  order by v.ord;
end $function$
